package com.vinnyvangogh.questpath;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Every quest, with what it needs and what it grants.
 *
 * <p>Bundled as a jar resource and generated by questpath's
 * {@code -export-quest-graph}. Nobody transcribes 218 quests by hand, and the
 * bundle is what lets the panel answer without questpath running — which is
 * the difference between a plugin and a remote control.
 *
 * <p>It goes stale: the graph updates when this plugin is released, not when
 * the wiki changes. That is a real cost and the reason questpath stays the
 * place where a correction lands first.
 */
class QuestGraph
{
	/**
	 * The graph shape this build understands.
	 *
	 * A version it does not know is refused rather than parsed. A graph
	 * missing a field parses cleanly into nulls and then answers "eligible"
	 * for a quest whose requirements were never read — a confident wrong
	 * answer, which is the one thing this plugin must not produce.
	 *
	 * 2 added Item.sources(). 3 added Item.itemId(), which is what the
	 * overlays draw the game's own sprite from -- searching the item cache by
	 * name instead would re-derive a disambiguation questpath's 16,472-row
	 * catalogue has already done, and get it wrong: "Bucket" matches a
	 * Meiyerditch bucket and an animation-only bucket as readily as the real
	 * one. 4 added Item.unresolved(), the wiki lines the catalogue could not
	 * place -- 354 of 1,301 -- which used to be dropped from the bundle
	 * without trace, leaving every quest's item list quietly short while
	 * presenting itself as the list. 5 added boosts(). 6 added
	 * prerequisitesStartedOnly().
	 *
	 * <p>7 added shops() and Item.shopNames(): a top-level table of 166 shops
	 * with a walkable tile, and per-item the names of the shops in that table
	 * which sell it. Before this, an item's sources() were display strings
	 * only -- "Shop: Tynan's Fishing Supplies (2 Coins)" -- with nothing a
	 * pathfinder could walk to, which is why {@link ShortestPathBridge} had
	 * no real destinations to hand Shortest Path and the Items tab's own
	 * route button stayed permanently disabled. A bundle missing this field
	 * would parse an item's shop names as absent rather than "not sent yet",
	 * which is indistinguishable from "this item cannot be bought" -- exactly
	 * the confident-wrong-answer shape every earlier bump exists to refuse.
	 *
	 * <p>8 added Quest.startX()/startY(): where the quest itself begins, for
	 * 205 of 218 quests. These are the quest's *start*, never a per-step
	 * location -- the wiki publishes no per-step coordinates, questpath's own
	 * attempt to derive them placed only 16% of 7,327 steps, and Quest
	 * Helper hand-writes every step location instead, fifteen {@code
	 * WorldPoint}s in Cook's Assistant alone. That gap is exactly why this
	 * plugin hands a quest off to Quest Helper once the player reaches its
	 * door rather than trying to guide them through it: getting someone to
	 * the start is a coordinate this bundle can carry honestly, and guiding
	 * them through the quest is not. (0, 0) is a real tile on the game's own
	 * grid, so the 13 quests with no known start omit both keys rather than
	 * sending zeros, and a parser that read a missing key as zero would send
	 * someone confidently to the game's origin. A bundle older than 8 has no
	 * start field to fall back to at all, which is exactly why an older
	 * bundle must be refused rather than read as "no quest has a start" --
	 * that is a different, false claim from "this build does not know yet".
	 *
	 * <p>12 added {@code diary_tasks}: every achievement diary task, its
	 * (tier_id, ordinal) identity -- never a row id, because the ingest
	 * deletes and reinserts every tier's tasks on each re-ingest and a row id
	 * would not survive that -- and every world location questpath could
	 * place for it. A bundle missing this field would parse every diary task
	 * as nonexistent rather than as "this build predates diary routing",
	 * which is exactly the confident-wrong-answer shape every earlier bump
	 * exists to refuse: the diary route would silently have nothing to route
	 * to, rather than the plugin refusing the whole graph outright. Tasks
	 * with no known location are still included, with an empty {@code
	 * locations} list -- that is a real, checked fact ("questpath does not
	 * know where this is"), not an absent field, and {@link
	 * DiaryTask#locations()} stays empty for it rather than null either way.
	 */
	static final int SUPPORTED_VERSION = 12;

	/**
	 * The newest version this build also reads. 13 adds {@code
	 * recommended_items} on each quest -- the wiki's "recommended" list,
	 * resolved to catalogue items -- and nothing else changes shape, so a
	 * v12 document still parses: every field v12 promised is present, and
	 * the one field it lacks is optional in the sense that matters, because
	 * {@link QuestItems#graphCarriesRecommended()} exists to tell a v12
	 * graph's "cannot say" apart from a v13 graph's "nothing recommended".
	 * That is the one case where tolerating the older version is honest
	 * rather than confident-wrong, and it is why {@link #SUPPORTED_VERSION}
	 * stays at 12 while the bundled copy is still exported at 12.
	 *
	 * <p>14 adds three optional top-level tables: {@code recipes} (how an
	 * item is made, from what, at which facility, at which levels), {@code
	 * facilities} (where those facilities stand) and {@code drop_sources}
	 * (what gates a monster: boss, Slayer level, combat level). Additive in
	 * the same way 13 was: absent means "this export predates making and
	 * drop gating", and the route then behaves exactly as it did on 13.
	 */
	static final int MAX_VERSION = 14;

	@SerializedName("version")
	private int version;

	@SerializedName("drop_locations")
	private List<DropLocation> dropLocations;

	@SerializedName("quests")
	private List<Quest> quests;

	@SerializedName("boosts")
	private List<Boost> boosts;

	@SerializedName("shops")
	private List<Shop> shops;

	/**
	 * Every achievement diary task in the game, account-agnostic -- see
	 * {@link #SUPPORTED_VERSION}'s own doc for why a v12 graph missing this
	 * key entirely is refused rather than read as "no diary tasks exist".
	 * Left {@code null} when the key is absent so {@link
	 * #parse(Gson, Reader)} can tell that apart from a present, empty array;
	 * {@link #diaryTasks()} is the null-safe accessor every other caller
	 * should use.
	 */
	@SerializedName("diary_tasks")
	private List<DiaryTask> diaryTasks;

	/** How items are made -- see {@link Recipe}. Absent before version 14. */
	@SerializedName("recipes")
	private List<Recipe> recipes;

	/**
	 * Where furnaces, anvils and ranges stand, by the name a {@link
	 * Recipe#facility()} uses. The same name-and-tile shape as a {@link Shop}
	 * (only name, x, y and plane are sent), so it is read as one rather than
	 * as a copy of it.
	 */
	@SerializedName("facilities")
	private List<Shop> facilities;

	/** What gates each monster that drops something -- see {@link DropSource}. */
	@SerializedName("drop_sources")
	private List<DropSource> dropSources;

	/**
	 * One way to make an item: what goes in, where, and at what levels.
	 *
	 * <p>Molten glass is a Bucket of sand and a Soda ash at a Furnace, at 1
	 * Crafting. A material can itself be the product of another recipe;
	 * nesting is expressed by name, never by embedding, so one ingredient is
	 * described once however many recipes use it.
	 */
	static class Recipe
	{
		@SerializedName("product")
		private String product;

		@SerializedName("product_item_id")
		private int productItemId;

		@SerializedName("output_quantity")
		private int outputQuantity;

		@SerializedName("facility")
		private String facility;

		@SerializedName("members")
		private boolean members;

		@SerializedName("skills")
		private List<Requirement> skills;

		@SerializedName("materials")
		private List<Material> materials;

		Recipe()
		{
		}

		Recipe(String product, String facility, List<Requirement> skills, List<Material> materials)
		{
			this.product = product;
			this.facility = facility;
			this.skills = skills;
			this.materials = materials;
			this.outputQuantity = 1;
		}

		String product()
		{
			return product == null ? "" : product;
		}

		int productItemId()
		{
			return productItemId;
		}

		/** How many one make produces; never below one. */
		int outputQuantity()
		{
			return Math.max(1, outputQuantity);
		}

		/** "Furnace", "Anvil", "Range" -- or empty for an item made anywhere. */
		String facility()
		{
			return facility == null ? "" : facility;
		}

		boolean members()
		{
			return members;
		}

		List<Requirement> skills()
		{
			return skills == null ? Collections.emptyList() : skills;
		}

		List<Material> materials()
		{
			return materials == null ? Collections.emptyList() : materials;
		}
	}

	/**
	 * One input to a recipe, with where it comes from.
	 *
	 * <p>Carries its own shops and droppers because an ingredient is usually
	 * not a quest item itself, so no quest line would otherwise say where a
	 * Bucket of sand is sold.
	 */
	static class Material
	{
		@SerializedName("name")
		private String name;

		@SerializedName("item_id")
		private int itemId;

		@SerializedName("quantity")
		private int quantity;

		@SerializedName("shop_names")
		private List<String> shopNames;

		@SerializedName("drop_source_names")
		private List<String> dropSourceNames;

		Material()
		{
		}

		Material(String name, int quantity, List<String> shopNames, List<String> dropSourceNames)
		{
			this.name = name;
			this.quantity = quantity;
			this.shopNames = shopNames;
			this.dropSourceNames = dropSourceNames;
		}

		String name()
		{
			return name == null ? "" : name;
		}

		int itemId()
		{
			return itemId;
		}

		/** How many one make consumes; never below one. */
		int quantity()
		{
			return Math.max(1, quantity);
		}

		List<String> shopNames()
		{
			return shopNames == null ? Collections.emptyList() : shopNames;
		}

		List<String> dropSourceNames()
		{
			return dropSourceNames == null ? Collections.emptyList() : dropSourceNames;
		}
	}

	/**
	 * What it takes to kill a monster for its drop.
	 *
	 * <p>The answer to a route that sent a low-level Group Ironman to the
	 * Thermonuclear smoke devil for Molten glass: a boss behind 93 Slayer is
	 * where that item drops, and nowhere a route should go.
	 */
	static class DropSource
	{
		@SerializedName("name")
		private String name;

		@SerializedName("slayer_level")
		private int slayerLevel;

		@SerializedName("combat_level")
		private int combatLevel;

		@SerializedName("boss")
		private boolean boss;

		DropSource()
		{
		}

		DropSource(String name, int slayerLevel, int combatLevel, boolean boss)
		{
			this.name = name;
			this.slayerLevel = slayerLevel;
			this.combatLevel = combatLevel;
			this.boss = boss;
		}

		String name()
		{
			return name == null ? "" : name;
		}

		/** The Slayer level needed to damage it; 0 when there is none. */
		int slayerLevel()
		{
			return slayerLevel;
		}

		/** A combat level the account needs to reach it; 0 when there is none. */
		int combatLevel()
		{
			return combatLevel;
		}

		boolean boss()
		{
			return boss;
		}
	}

	/**
	 * One place to buy something, as the verdict engine's caller needs it: a
	 * name to match against {@link Item#shopNames()} and a tile to hand a
	 * pathfinder.
	 *
	 * Only shops questpath could place carry a coordinate at all -- see
	 * {@link #shops()} -- so every {@code Shop} this class parses is a real,
	 * walkable destination, never a placeholder.
	 */
	static class Shop
	{
		@SerializedName("name")
		private String name;

		@SerializedName("x")
		private int x;

		@SerializedName("y")
		private int y;

		@SerializedName("plane")
		private int plane;

		@SerializedName("town")
		private String town;

		@SerializedName("reachability")
		private Reachability reachability;

		/**
		 * What this shop is behind, or null when it is behind nothing --
		 * which is most of them (47 of 166 carry anything at all).
		 */
		Reachability reachability()
		{
			return reachability;
		}

		String name()
		{
			return name == null ? "" : name;
		}

		int x()
		{
			return x;
		}

		int y()
		{
			return y;
		}

		/** The height level. 0 for ground floor, which is nearly every shop. */
		int plane()
		{
			return plane;
		}

		/** The wiki's own name for where this is, or empty when it resolved to none. */
		String town()
		{
			return town == null ? "" : town;
		}
	}

	/**
	 * One achievement diary task, account-agnostic: what it says and where it
	 * can be done. Never carries completion -- that is per-account, and rides
	 * the push response instead, in {@link PushResponse.Diary}.
	 *
	 * <p><b>Identified by {@link #tierId()} and {@link #ordinal()} together,
	 * never by a row id of its own -- this class has none.</b> The Go
	 * ingest deletes and reinserts every tier's tasks on each re-ingest, so a
	 * row id would change under a task that never moved, silently
	 * disconnecting any per-account state keyed by it. {@code tierId} is
	 * stable (the ingest upserts tiers by diary and tier name) and {@code
	 * ordinal} is the task's fixed position within its tier, so the pair
	 * survives a re-ingest even though no single field does.
	 */
	static class DiaryTask
	{
		@SerializedName("tier_id")
		private long tierId;

		@SerializedName("ordinal")
		private int ordinal;

		@SerializedName("diary")
		private String diary;

		@SerializedName("tier")
		private String tier;

		@SerializedName("text")
		private String text;

		@SerializedName("locations")
		private List<Location> locations;

		/** The tier this task belongs to, stable across a re-ingest -- see the class doc. */
		long tierId()
		{
			return tierId;
		}

		/** This task's fixed position within its tier -- see the class doc. */
		int ordinal()
		{
			return ordinal;
		}

		/** The diary's own name, e.g. "Ardougne". */
		String diary()
		{
			return diary == null ? "" : diary;
		}

		/** The tier's own name, e.g. "Easy". */
		String tier()
		{
			return tier == null ? "" : tier;
		}

		/** The task's own text, verbatim from the wiki. */
		String text()
		{
			return text == null ? "" : text;
		}

		/**
		 * Every world location this task could be done at, best first as the
		 * wiki gave them. Empty -- never null -- when questpath knows of
		 * none for this task; that is a real, checked fact ("location
		 * unknown"), not a gap to guess at, and callers must render it as
		 * such rather than route to nothing.
		 */
		List<Location> locations()
		{
			return locations == null ? Collections.emptyList() : locations;
		}
	}

	/**
	 * One place a {@link DiaryTask} can be done, as a raw tile: the caller
	 * builds a {@code WorldPoint} from {@link #x()}, {@link #y()} and {@link
	 * #plane()} itself, the same convention {@link Shop} and {@link
	 * DropLocation} already use, so this model class carries no dependency on
	 * {@code net.runelite.api}.
	 */
	static class Location
	{
		@SerializedName("page_name")
		private String pageName;

		@SerializedName("x")
		private int x;

		@SerializedName("y")
		private int y;

		@SerializedName("plane")
		private int plane;

		/** The wiki page this location came from. */
		String pageName()
		{
			return pageName == null ? "" : pageName;
		}

		int x()
		{
			return x;
		}

		int y()
		{
			return y;
		}

		/** The height level. 0 for ground floor. */
		int plane()
		{
			return plane;
		}
	}

	/**
	 * One temporary skill boost, with the size the requirement flag never
	 * had.
	 *
	 * A requirement's {@code boostable} is a bare yes from the wiki: it says
	 * a boost is allowed and never how large one can be. Without these, a
	 * fifty-level shortfall and a one-level shortfall are indistinguishable,
	 * which is the bug they exist to close.
	 */
	static class Boost
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("item")
		private String item;

		@SerializedName("base")
		private int base;

		@SerializedName("per_level")
		private double perLevel;

		@SerializedName("max")
		private int max;

		@SerializedName("random")
		private boolean random;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		String item()
		{
			return item == null ? "" : item;
		}

		/** The increase at level 0, or the whole increase when flat. */
		int base()
		{
			return base;
		}

		/** The fraction of the account's level added on top; zero when flat. */
		double perLevel()
		{
			return perLevel;
		}

		/** The wiki's stated ceiling, or zero when it states one number. */
		int max()
		{
			return max;
		}

		/** Whether this one can drain instead of boosting -- the stews. */
		boolean random()
		{
			return random;
		}
	}

	/** One quest as the verdict engine sees it. */
	static class Quest
	{
		@SerializedName("id")
		private long id;

		@SerializedName("slug")
		private String slug;

		@SerializedName("name")
		private String name;

		@SerializedName("members")
		private boolean members;

		/**
		 * Boxed, not primitive: 13 of 218 quests carry neither key at all
		 * rather than a zero, because (0, 0) is a real, walkable tile on the
		 * game's own grid and a primitive default of 0 would be
		 * indistinguishable from it. {@link #hasStart()} is the only safe way
		 * to ask whether this quest has one.
		 */
		@SerializedName("start_x")
		private Integer startX;

		@SerializedName("start_y")
		private Integer startY;

		@SerializedName("prerequisites")
		private List<Long> prerequisites;

		@SerializedName("prerequisites_started_only")
		private List<Long> prerequisitesStartedOnly;

		@SerializedName("requirements")
		private List<Requirement> requirements;

		@SerializedName("rewards")
		private List<Reward> rewards;

		@SerializedName("items")
		private List<Item> items;

		@SerializedName("recommended_items")
		private List<Item> recommendedItems;

		long id()
		{
			return id;
		}

		String slug()
		{
			return slug == null ? "" : slug;
		}

		String name()
		{
			return name == null ? "" : name;
		}

		boolean members()
		{
			return members;
		}

		/**
		 * Whether this quest carries a start point at all.
		 *
		 * 13 of 218 quests do not -- the wiki gave questpath's exporter
		 * nothing to place -- and {@link #startX()}/{@link #startY()} are
		 * meaningless for those; a caller must check this first, the same
		 * way a shop lookup must check for null rather than trust a zeroed
		 * coordinate.
		 */
		boolean hasStart()
		{
			return startX != null && startY != null;
		}

		/**
		 * The quest's start point x tile. Meaningless unless {@link
		 * #hasStart()} -- see that method's doc for why 0 is never a safe
		 * default here.
		 *
		 * <p>This is where the quest <i>begins</i>, never a per-step location:
		 * the wiki publishes no per-step coordinates, questpath's own attempt
		 * to derive them placed only 16% of 7,327 steps, and Quest Helper
		 * hand-writes every step location instead -- fifteen {@code
		 * WorldPoint}s in Cook's Assistant alone. The honest use of this
		 * field is getting a player to the door and handing off, never
		 * drawing a route through the quest itself.
		 */
		int startX()
		{
			return startX == null ? 0 : startX;
		}

		/** The quest's start point y tile. See {@link #startX()}. */
		int startY()
		{
			return startY == null ? 0 : startY;
		}

		List<Long> prerequisites()
		{
			return prerequisites == null ? Collections.emptyList() : prerequisites;
		}

		/**
		 * The subset of {@link #prerequisites()} satisfied by having *started*
		 * the quest rather than finished it -- the wiki's "Started [[X]]"
		 * phrasing. Both planners must apply this identically or their
		 * verdicts diverge, which is what PlannerVectorsTest exists to catch.
		 */
		boolean requiresStartedOnly(long prerequisiteId)
		{
			if (prerequisitesStartedOnly == null)
			{
				return false;
			}
			return prerequisitesStartedOnly.contains(prerequisiteId);
		}

		List<Requirement> requirements()
		{
			return requirements == null ? Collections.emptyList() : requirements;
		}

		List<Reward> rewards()
		{
			return rewards == null ? Collections.emptyList() : rewards;
		}

		List<Item> items()
		{
			return items == null ? Collections.emptyList() : items;
		}

		public List<Item> recommendedItems()
		{
			return recommendedItems == null ? Collections.emptyList() : recommendedItems;
		}
	}

	/** One thing a quest needs, already resolved to a catalogue item name. */
	/**
	 * What an account must have to walk into a shop and be served.
	 *
	 * <p>Absent on most shops, and absent means open. Present, it is the
	 * reason a shop must be left off a trip rather than named as a
	 * destination -- the Fishing Guild Shop sells a big fishing net behind 68
	 * Fishing, and an account with 59 was being sent there while a shop in
	 * Catherby selling the same net went unmentioned.
	 */
	static class Reachability
	{
		@SerializedName("required_skills")
		private List<SkillGate> requiredSkills;

		@SerializedName("required_quest_ids")
		private List<Integer> requiredQuestIds;

		@SerializedName("required_quest_ids_started_only")
		private List<Integer> startedOnlyQuestIds;

		@SerializedName("unknown")
		private boolean unknown;

		/**
		 * True when the export could not work out what gates the shop. Not a
		 * statement that it is open: an unknown stays unknown, and
		 * {@link ShopReachability} treats it as unreachable.
		 */
		boolean unknown()
		{
			return unknown;
		}

		/** Skill levels needed to get in. Empty when none are. */
		List<SkillGate> requiredSkills()
		{
			return requiredSkills == null ? List.of() : requiredSkills;
		}

		/** Quests needed to get in, by graph id. */
		List<Integer> requiredQuestIds()
		{
			return requiredQuestIds == null ? List.of() : requiredQuestIds;
		}

		/**
		 * The subset of {@link #requiredQuestIds()} satisfied by merely
		 * having started the quest.
		 *
		 * <p>Uglug Nar is the case this exists for: his shop opens after
		 * being handed a Relicym's balm *during* Zogre Flesh Eaters, which is
		 * a moment inside a quest rather than a state of one. It cannot be
		 * checked exactly, but "you must be able to start it" is a sound
		 * lower bound on every moment inside it -- weaker than the truth and
		 * never wrong in the direction that wastes a trip.
		 */
		List<Integer> startedOnlyQuestIds()
		{
			return startedOnlyQuestIds == null ? List.of() : startedOnlyQuestIds;
		}
	}

	/** One skill level a place demands, and whether a boost counts. */
	static class SkillGate
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("level")
		private int level;

		@SerializedName("boostable")
		private boolean boostable;

		/** The skill's name, lowercase as the bundle spells it. */
		String skill()
		{
			return skill == null ? "" : skill;
		}

		/** The level needed. */
		int level()
		{
			return level;
		}

		/**
		 * Whether a temporary boost gets you in.
		 *
		 * <p>Only true where the wiki says so outright, so this under-claims:
		 * a chef's delight really does open the Cooks' Guild and the bundle
		 * records it as not boostable. Under-claiming costs a walk; the
		 * opposite costs a wasted trip.
		 */
		boolean boostable()
		{
			return boostable;
		}
	}

	/**
	 * Somewhere a monster that drops something can be found.
	 *
	 * <p>The answer to "for something like Bat bones, if there is no shop, it
	 * should route me to the nearest bats". An item names its droppers in
	 * {@link Item#dropSourceNames()}; this places them.
	 */
	static class DropLocation
	{
		@SerializedName("source_name")
		private String sourceName;

		@SerializedName("x")
		private int x;

		@SerializedName("y")
		private int y;

		@SerializedName("plane")
		private int plane;

		@SerializedName("region")
		private String region;

		/** The monster, spelled as item_sources spells it. */
		String sourceName()
		{
			return sourceName == null ? "" : sourceName;
		}

		int x()
		{
			return x;
		}

		int y()
		{
			return y;
		}

		int plane()
		{
			return plane;
		}

		/**
		 * Where this is, loosely -- "general", "wilderness", and so on.
		 *
		 * <p>Worth carrying rather than dropping: sending someone into the
		 * Wilderness without saying so is its own way of wasting a trip, and
		 * on a hardcore ironman it is considerably worse than that.
		 */
		String region()
		{
			return region == null ? "" : region;
		}
	}


	/**
	 * One item that satisfies a category requirement -- one pickaxe out of
	 * the set "any pickaxe" means.
	 */
	static class Alternative
	{
		@SerializedName("name")
		private String name;

		@SerializedName("item_id")
		private int itemId;

		@SerializedName("requirements")
		private List<Requirement> requirements;

		String name()
		{
			return name == null ? "" : name;
		}

		/** The game's own item id, or 0 for "draw no icon" -- see {@link Item#itemId()}. */
		int itemId()
		{
			return itemId;
		}

		/**
		 * The levels the wiki states for this member, each with its own
		 * skill.
		 *
		 * <p><b>Separate, and the separation is load-bearing.</b> A pickaxe
		 * states Mining and Attack. Mining gates using it; Attack only gates
		 * wielding it, and a pickaxe mines perfectly well from the
		 * inventory. An account hard-capping Attack can therefore use a rune
		 * pickaxe it could never wield -- and that account is the entire
		 * reason questpath exists, so the caller decides which of these bind
		 * rather than this collapsing them into one number.
		 */
		List<Requirement> requirements()
		{
			return requirements == null ? Collections.emptyList() : requirements;
		}
	}

	static class Item
	{
		@SerializedName("name")
		private String name;

		@SerializedName("item_id")
		private int itemId;

		@SerializedName("quantity")
		private int quantity;

		@SerializedName("unresolved")
		private boolean unresolved;

		@SerializedName("optional")
		private boolean optional;

		@SerializedName("obtainable")
		private boolean obtainable;

		@SerializedName("sources")
		private List<String> sources;

		@SerializedName("shop_names")
		private List<String> shopNames;

		@SerializedName("drop_source_names")
		private List<String> dropSourceNames;

		@SerializedName("notes")
		private List<String> notes;

		@SerializedName("group_name")
		private String groupName;

		@SerializedName("alternatives")
		private List<Alternative> alternatives;

		/**
		 * The monsters that drop this, for an item no shop sells. Matched
		 * against {@link DropLocation#sourceName()}.
		 */
		List<String> dropSourceNames()
		{
			return dropSourceNames == null ? List.of() : dropSourceNames;
		}

		/**
		 * The wiki's own parentheticals for this line, verbatim and in order
		 * -- "4 if you want your own blurite sword", "can't be noted, but can
		 * be delivered in increments", "unnoted".
		 *
		 * <p>Nearly half the wiki's requirement lines carry one and the bundle
		 * used to drop every one of them. Reported from play: The Knight's
		 * Sword asks for "2 or 4 iron bars (4 if you want your own blurite
		 * sword)", questpath resolved it to two and said nothing about the
		 * four, and an ironman who wanted the second sword -- genuinely worth
		 * having in free-to-play -- bought two.
		 *
		 * <p><b>Show these verbatim and never parse them.</b> They say things
		 * no schema models, which is exactly why they are text. The two
		 * conditions that ARE modelled, {@link #optional()} and {@link
		 * #obtainable()}, are flags because they earned it; everything else
		 * stays prose and the player decides what it means.
		 */
		List<String> notes()
		{
			return notes == null ? Collections.emptyList() : notes;
		}

		/**
		 * The category this line names, when it names one rather than an item
		 * -- "Pickaxe", "Light sources". Empty for an ordinary item.
		 *
		 * <p>A grouped line has no {@link #itemId()}, because there is no one
		 * item to have: the requirement is the set in {@link
		 * #alternatives()}. It is nonetheless <b>not</b> {@link
		 * #unresolved()} -- questpath knows exactly what satisfies it, which
		 * is the whole difference. Treating the two the same is how "A light
		 * source" reached the Grand Exchange panel labelled "can't look up",
		 * for something the Grand Exchange plainly sells.
		 */
		String groupName()
		{
			return groupName == null ? "" : groupName;
		}

		/** Whether this line names a category rather than a single item. */
		boolean grouped()
		{
			return !groupName().isEmpty() && !alternatives().isEmpty();
		}

		/**
		 * The items that satisfy this line, in the wiki's own tier order --
		 * so the last one an account can use is the best one it can use.
		 *
		 * <p><b>Never re-sorted.</b> The order is the wiki's ranking, carried
		 * through the bundle untouched; re-deriving it here would replace a
		 * real ranking with an invented one.
		 */
		List<Alternative> alternatives()
		{
			return alternatives == null ? Collections.emptyList() : alternatives;
		}

		String name()
		{
			return name == null ? "" : name;
		}

		/**
		 * The count the wiki stated, or 0 when it stated none.
		 *
		 * Zero is not one. Plenty of lines name a thing without saying how
		 * many, and defaulting to one would invent a number the wiki did not
		 * give.
		 */
		int quantity()
		{
			return quantity;
		}

		/**
		 * The game's own item id, or 0 when questpath holds none.
		 *
		 * Zero means "no id", not item 0: questpath omits the field rather
		 * than sending a zero precisely so this stays unambiguous, because
		 * item 0 is a real item and would render as confident, wrong art for
		 * something the catalogue could not actually identify. Callers must
		 * treat 0 as "draw no icon".
		 */
		int itemId()
		{
			return itemId;
		}

		/**
		 * Whether this is a wiki line questpath could not match to a real
		 * item.
		 *
		 * name() then carries the wiki's own words rather than an item name,
		 * there is no id, and nothing can tick it against a bank. It is shown
		 * anyway: dropping it would make the rest of the list a lie, because
		 * the panel would present four items as everything the quest needs
		 * when the wiki listed five.
		 */
		boolean unresolved()
		{
			return unresolved;
		}

		boolean optional()
		{
			return optional;
		}

		/** Whether the wiki says this can be picked up during the quest itself. */
		boolean obtainable()
		{
			return obtainable;
		}

		/**
		 * Where to get this item, best first, as short display lines ready to
		 * show verbatim -- "Shop: Varrock General Store (5 gp)", "Drop: Goblin
		 * (common)". Empty when questpath found no source at all, which the
		 * panel must render as no tooltip, never an empty or invented one.
		 */
		List<String> sources()
		{
			return sources == null ? Collections.emptyList() : sources;
		}

		/**
		 * The shops in {@link QuestGraph#shops()} that sell this, best first.
		 *
		 * Names only, matched against {@link Shop#name()} exactly -- questpath
		 * emits both from the same lookup, so every name here is guaranteed to
		 * resolve against the graph's own shop table. Empty when nothing
		 * placeable sells this, which the caller must render as no route
		 * available, never as one with a shop that goes nowhere.
		 */
		List<String> shopNames()
		{
			return shopNames == null ? Collections.emptyList() : shopNames;
		}
	}

	/** A skill level a quest demands. */
	static class Requirement
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("level")
		private int level;

		@SerializedName("boostable")
		private boolean boostable;

		Requirement()
		{
		}

		Requirement(String skill, int level)
		{
			this.skill = skill;
			this.level = level;
		}

		String skill()
		{
			return skill == null ? "" : skill;
		}

		int level()
		{
			return level;
		}

		/**
		 * Boostable rescues a skill gap but never a cap violation: a boost is
		 * relative to the base level, so an Attack capped at 1 cannot reach a
		 * boostable requirement of 15.
		 */
		boolean boostable()
		{
			return boostable;
		}
	}

	/** Unavoidable experience a quest grants. */
	static class Reward
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("xp")
		private double xp;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		double xp()
		{
			return xp;
		}
	}

	private Map<Long, Quest> byId;
	private Map<String, Quest> byName;
	private Map<String, Shop> shopsByName;
	private transient Map<String, Item> itemsByName;

	int version()
	{
		return version;
	}

	List<Quest> quests()
	{
		return quests == null ? Collections.emptyList() : quests;
	}

	/** Every temporary skill boost the bundle carries. */
	List<Boost> boosts()
	{
		return boosts == null ? Collections.emptyList() : boosts;
	}

	/**
	 * Every shop the bundle's items can actually be bought at.
	 *
	 * Only shops with a real coordinate appear at all -- questpath does not
	 * export one it could not place -- so every entry here is a genuine
	 * destination, never a placeholder waiting on a tile nobody supplied.
	 */
	List<Shop> shops()
	{
		return shops == null ? Collections.emptyList() : shops;
	}

	/**
	 * Every achievement diary task in the game, account-agnostic -- see
	 * {@link #SUPPORTED_VERSION}'s own doc. Null-safe: {@link
	 * #parse(Gson, Reader)} is what refuses a v12 document missing the key
	 * entirely, so by the time a caller reaches this accessor the only
	 * remaining case for {@code null} is a test fixture built by hand, and
	 * even then this returns an empty list rather than throwing.
	 */
	List<DiaryTask> diaryTasks()
	{
		return diaryTasks == null ? Collections.emptyList() : diaryTasks;
	}

	/** One shop by its exact name, or null when the graph does not carry it. */
	Shop shop(String name)
	{
		if (shopsByName == null)
		{
			Map<String, Shop> index = new LinkedHashMap<>();
			for (Shop shop : shops())
			{
				index.put(shop.name(), shop);
			}
			shopsByName = index;
		}
		return shopsByName.get(name);
	}

	/**
	 * The first resolved, non-grouped item line anywhere in the graph with
	 * this name, matched case-insensitively -- or null.
	 *
	 * <p>Every line naming one item carries the same sources, shops and
	 * droppers (the export looks them up once per item), so any one of them
	 * stands for all. Used when questpath's item plan retargets a line to a
	 * member the line itself did not name, so the shop route can still find
	 * where that member comes from.
	 */
	Item itemNamed(String name)
	{
		if (name == null)
		{
			return null;
		}
		if (itemsByName == null)
		{
			Map<String, Item> index = new java.util.HashMap<>();
			for (Quest quest : quests())
			{
				for (Item item : quest.items())
				{
					if (item.unresolved() || item.grouped() || item.name() == null)
					{
						continue;
					}
					index.putIfAbsent(item.name().toLowerCase(), item);
				}
				for (Item item : quest.recommendedItems())
				{
					if (item.unresolved() || item.grouped() || item.name() == null)
					{
						continue;
					}
					index.putIfAbsent(item.name().toLowerCase(), item);
				}
			}
			itemsByName = index;
		}
		return itemsByName.get(name.toLowerCase());
	}

	/** One quest by id, or null when the graph does not carry it. */
	Quest get(long id)
	{
		if (byId == null)
		{
			Map<Long, Quest> index = new LinkedHashMap<>();
			for (Quest quest : quests())
			{
				index.put(quest.id(), quest);
			}
			byId = index;
		}
		return byId.get(id);
	}

	/**
	 * One quest by its exact name, or null when the graph does not carry it.
	 *
	 * Names rather than ids because that is what the client and the saved
	 * route both speak -- {@code net.runelite.api.Quest#getName()} and
	 * {@code NextQuestStatus.Step#questName()} are both game-name strings,
	 * never questpath's rowids.
	 */
	Quest byName(String name)
	{
		if (byName == null)
		{
			Map<String, Quest> index = new LinkedHashMap<>();
			for (Quest quest : quests())
			{
				index.put(quest.name(), quest);
			}
			byName = index;
		}
		return byName.get(name);
	}

	/**
	 * Loads the bundled graph.
	 *
	 * <p>{@code getResourceAsStream}, never {@code getResource}: resources
	 * ship inside a jar, and a URL to one is not a file path.
	 *
	 * @throws IOException when the resource is missing, unreadable, or carries
	 *     a version this build does not understand
	 */
	/** Every known monster drop location. Empty in a bundle older than 9. */
	List<DropLocation> dropLocations()
	{
		return dropLocations == null ? List.of() : dropLocations;
	}

	/** Every recipe the export carries. Empty in a bundle older than 14. */
	List<Recipe> recipes()
	{
		return recipes == null ? List.of() : recipes;
	}

	/** Every placed facility. Empty in a bundle older than 14. */
	List<Shop> facilities()
	{
		return facilities == null ? List.of() : facilities;
	}

	/** What gates each dropper. Empty in a bundle older than 14. */
	List<DropSource> dropSources()
	{
		return dropSources == null ? List.of() : dropSources;
	}

	static QuestGraph load(Gson gson) throws IOException
	{
		try (InputStream stream = QuestGraph.class.getResourceAsStream("quests.json"))
		{
			if (stream == null)
			{
				throw new IOException("bundled quests.json is missing from the jar");
			}
			try
			{
				return parse(gson, new InputStreamReader(stream, StandardCharsets.UTF_8));
			}
			catch (IOException e)
			{
				throw new IOException("bundled quests.json: " + e.getMessage(), e);
			}
		}
	}

	/**
	 * Parses and validates a graph document already in hand, against exactly
	 * the same rules {@link #load(Gson)} always held the bundled resource to:
	 * it must parse, name a version this build understands, and carry at
	 * least one quest.
	 *
	 * <p>Pulled out so a graph fetched live from a questpath instance (see
	 * {@link QuestGraphFetcher}) is held to the identical bar as the one
	 * baked into the jar. There must never be two ideas of what makes a
	 * quest graph trustworthy -- one lenient because it came over the
	 * network -- because the entire reason {@link #SUPPORTED_VERSION} exists
	 * is that a graph missing a field must be refused outright rather than
	 * parsed into a confident, wrong answer, and that has to be true no
	 * matter where the bytes came from.
	 *
	 * @throws IOException when the document does not parse, or parses to a
	 *     version this build does not understand, or carries no quests
	 */
	static QuestGraph parse(Gson gson, Reader reader) throws IOException
	{
		QuestGraph graph;
		try
		{
			graph = gson.fromJson(reader, QuestGraph.class);
		}
		catch (JsonSyntaxException e)
		{
			throw new IOException("did not parse as a quest graph: " + e.getMessage(), e);
		}
		if (graph == null)
		{
			throw new IOException("did not parse as a quest graph");
		}
		if (graph.version() < SUPPORTED_VERSION || graph.version() > MAX_VERSION)
		{
			throw new IOException(graph.version() > MAX_VERSION
				? "is version " + graph.version() + ", which this build (" + MAX_VERSION
					+ ") does not understand yet -- update the plugin"
				: "is version " + graph.version() + ", which is older than this build ("
					+ SUPPORTED_VERSION + ") expects -- questpath needs re-exporting or upgrading");
		}
		if (graph.quests().isEmpty())
		{
			// An empty graph makes every quest unknown, which renders as
			// "not found" rather than as "the graph is broken".
			throw new IOException("carries no quests");
		}
		if (graph.diaryTasks == null)
		{
			// The raw field, not diaryTasks() -- that accessor already turns
			// null into an empty list, which is exactly the confident-wrong
			// reading this check exists to refuse. A present, empty array
			// (every task genuinely has no location, or the export ran with
			// none staged) is a real answer and parses through; only the key
			// being absent entirely means this document predates diary
			// routing and must be refused the same way a missing shops table
			// or a missing boost table already is -- see
			// SUPPORTED_VERSION's own doc for the "diary route would
			// silently have nothing to route to" hazard this closes.
			throw new IOException("carries no diary_tasks field -- a v12 graph must include it, even empty");
		}
		return graph;
	}
}
